async function readApiResponse(response) {
  const body = await response.text();
  let data = {};
  if (body.trim()) {
    try { data = JSON.parse(body); }
    catch {
      const hint = response.status >= 500 ? ' Check that the Flask backend and configured database are running.' : '';
      throw Error(`Backend returned an unreadable response (HTTP ${response.status}).${hint}`);
    }
  } else if (!response.ok) {
    const hint = response.status >= 500 ? ' Check that the Flask backend and configured database are running.' : '';
    throw Error(`Backend returned an empty response (HTTP ${response.status}).${hint}`);
  }
  if (!response.ok) throw Error(data.error || `Request failed (HTTP ${response.status})`);
  return data;
}
