  cells.sort(() => Math.random() - 0.5);
  cells.slice(0, Math.min(+settings.obstacles, 120)).forEach(([r, c]) => { grid[r][c] = -1; });
  if (settings.roadCondition === 'poor') cells.slice(+settings.obstacles).forEach(([r, c]) => { if (Math.random() < 0.25) grid[r][c] = 2 + Math.floor(Math.random() * 2); });
  const free = cells.filter(([r, c]) => grid[r][c] >= 0);
