  while (queue.length) { const point = queue.shift(), pointId = id(point); visited.push(point); if (pointId === id(goal)) { const path = []; for (let current = point; current; current = parents[id(current)]) path.unshift(current); return { found: true, path, visited, frontier: [], cost: path.length - 1, nodesExplored: visited.length, executionTime: 0, memoryUsage: visited.length * 72, pathLength: path.length - 1 }; }
    [[1,0],[-1,0],[0,1],[0,-1]].forEach(([r,c]) => { const next = [point[0] + r, point[1] + c], nextId = id(next); if (next[0] >= 0 && next[0] < grid.length && next[1] >= 0 && next[1] < grid[0].length && grid[next[0]][next[1]] >= 0 && !(nextId in parents)) { parents[nextId] = point; queue.push(next); } }); }
  return { found: false, path: [], visited, frontier: [], cost: 0, nodesExplored: visited.length, executionTime: 0, memoryUsage: visited.length * 72, pathLength: 0 };
