  if (path === '/planning') { let current = body.team, victims = [...body.victims], totalCost = 0; const order = []; while (victims.length) { const choices = victims.map(victim => [localSearch(body.grid, current, victim), victim]).filter(([result]) => result.found); if (!choices.length) break; const [result, victim] = choices.sort((a, b) => a[0].cost - b[0].cost)[0]; order.push({ victim, path: result.path, cost: result.cost }); totalCost += result.cost; current = victim; victims = victims.filter(candidate => candidate !== victim); } return { order, totalCost, unreachable: victims }; }
