  if (path.startsWith('/auth/')) { const accounts = readLocal('accounts', []); if (path.endsWith('register')) { if (accounts.some(account => account.email === body.email.toLowerCase())) throw Error('Email is already registered on this device'); const user = { id: crypto.randomUUID?.() || String(Date.now()), name: body.name, email: body.email.toLowerCase(), role: body.role || 'citizen' }; accounts.push({ ...user, password: body.password }); writeLocal('accounts', accounts); return { token: 'offline-session', user }; } const account = accounts.find(candidate => candidate.email === body.email.toLowerCase() && candidate.password === body.password); if (!account) throw Error('No matching offline account. Register an account on this device first.'); const { password, ...user } = account; return { token: 'offline-session', user }; }
